template:
use std::slice;

fn sum_raw(ptr: *const i32, len: usize) -> i32 {
    let items = ⟦unsafe_kw⟧ {
        slice::⟦slice_fn⟧(ptr, len)
    };
    items.iter().sum()
}

fn main() {
    let numbers = [10, 20, 30];
    let total = sum_raw(numbers.as_ptr(), numbers.len());
    println!("{total}");
}

tests:
#[test]
fn sums_slice() {
    let numbers = [10, 20, 30];
    assert_eq!(sum_raw(numbers.as_ptr(), numbers.len()), 60);
}
